# Set up a working tree from a fresh clone.
#
#   .\setup.ps1                # fetch engine + libchdr, install the title config, build
#   .\setup.ps1 -SkipBuild     # fetch and install only
#
# You still supply the game: a .gdi dump of Draconus: Cult of the Wyrm (USA, V1.000).
# Nothing from the disc is downloaded, committed or generated by this script.
param(
    [switch]$SkipBuild,
    [string]$Sdl3Dir = ""
)

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$engine = Join-Path $root "engine"
$dl = Join-Path $root "work\dl"

# The engine is pinned to the commit this project was developed against.
$EngineUrl = "https://codeload.github.com/phobos665/dream-recomp/zip/51ca2766d2ebeae9caacda4e305eacb88cf64013"
$EnginePin = "51ca2766d2ebeae9caacda4e305eacb88cf64013"

# libchdr is the engine's only submodule. It is not pinned here; see docs/LEGAL.md.
$LibchdrUrl = "https://codeload.github.com/rtissera/libchdr/zip/refs/heads/master"

function Get-Zip($url, $dest) {
    New-Item -ItemType Directory -Force $dl | Out-Null
    $zip = Join-Path $dl ((Split-Path $dest -Leaf) + ".zip")
    curl.exe -L --fail --silent --show-error -o $zip $url
    $tmp = Join-Path $dl ((Split-Path $dest -Leaf) + "-src")
    if (Test-Path $tmp) { Remove-Item $tmp -Recurse -Force }
    Expand-Archive -LiteralPath $zip -DestinationPath $tmp -Force
    $inner = Get-ChildItem $tmp -Directory | Select-Object -First 1
    New-Item -ItemType Directory -Force $dest | Out-Null
    Copy-Item (Join-Path $inner.FullName "*") $dest -Recurse -Force
}

if (-not (Test-Path (Join-Path $engine "CMakeLists.txt"))) {
    Write-Host "fetching dream-recomp @ $EnginePin"
    Get-Zip $EngineUrl $engine
}
if (-not (Test-Path (Join-Path $engine "third_party\libchdr\CMakeLists.txt"))) {
    Write-Host "fetching libchdr"
    Get-Zip $LibchdrUrl (Join-Path $engine "third_party\libchdr")
}

# Our title configuration lives in this repository, outside the engine, so an engine update
# never overwrites it. Per-game extracted data is not copied: it is the owner's.
foreach ($game in Get-ChildItem (Join-Path $root "game") -Directory) {
    $target = Join-Path $engine "games\$($game.Name)"
    New-Item -ItemType Directory -Force $target | Out-Null
    Copy-Item (Join-Path $game.FullName "*.toml") $target -Force
    Copy-Item (Join-Path $game.FullName "CMakeLists.txt") $target -Force
    Write-Host "installed title config: games\$($game.Name)"
}

if ($SkipBuild) {
    Write-Host "`nnext: edit engine\games\draconus\draconus.toml -> [disc] image, then run the build in docs/09-TOOLING.md"
    return
}

$vc = "C:\Program Files (x86)\Microsoft Visual Studio\2022\BuildTools\VC\Auxiliary\Build\vcvars64.bat"
if (-not (Test-Path $vc)) { throw "Visual Studio 2022 Build Tools not found: $vc" }

$cmakeArgs = @(
    "-S", ".", "-B", "build-render", "-G", "Ninja",
    "-DCMAKE_BUILD_TYPE=Release",
    "-DDREAM_DEV_INTERPRETER=ON", "-DDREAM_RENDERER=ON",
    "-DDREAM_BUILD_TESTS=OFF", "-DDREAM_WERROR=OFF"
)
if ($Sdl3Dir) { $cmakeArgs += "-DSDL3_DIR=$Sdl3Dir" }

Push-Location $engine
try {
    cmd /c "`"$vc`" >nul && cmake $($cmakeArgs -join ' ')"
    cmd /c "`"$vc`" >nul && cmake --build build-render --target draconus_boot --parallel"
} finally {
    Pop-Location
}

Write-Host "`nbuilt: engine\build-render\games\draconus\draconus_boot.exe"
Write-Host "edit engine\games\draconus\draconus.toml -> [disc] image first, then run .\play-draconus.bat"
